mapper.select:
SELECT station_id,
       china_name AS stationName,
       region_id,
       manage_type
FROM spc_station
WHERE manage_type = #{manageType}

    AND region_id = #{regionId}



    AND (
        china_name LIKE #{keywordLike}
        OR station_id LIKE #{keywordLike}
    )

ORDER BY region_id ASC, china_name ASC
